#include "test.hpp"
#include "mspa/mspa.hpp"
#include <limits>
using namespace mspa;
int main(){RuntimeLimits l{};l.max_beliefs_per_agent=1;AgentPsychState s{};s.id={WorldId(1),1};BeliefState b{};b.id=BeliefId(1);b.proposition.predicate=PredicateId(1);b.proposition.name_space=NamespaceId(1);b.certainty=0.5f;s.beliefs={b,b};require(!validate_agent_state(s,l),"belief quota");RuntimeLimits bad{};bad.max_agents=HardLimits::max_agents+1;require(!validate_limits(bad),"hard limits");Proposition p{};p.predicate=PredicateId(1);p.name_space=NamespaceId(1);for(int i=0;i<300;++i)p.arguments.push_back({"x"+std::to_string(i),"v"});require(!validate_proposition_deep(p,RuntimeLimits{}),"argument quota");std::vector<std::uint8_t>garbage(1024,0xff);for(std::size_t n=0;n<garbage.size();n+=31){std::vector<std::uint8_t>x(garbage.begin(),garbage.begin()+static_cast<std::ptrdiff_t>(n));require(!deserialize_agent(x),"fuzz-like malformed bytes rejected");}RuntimeConfig c{};c.runtime_id=RuntimeId(1);c.world_id=WorldId(1);c.time_domain={TimeDomainId(1),{1,1}};auto r1=Runtime::create(c);c.runtime_id=RuntimeId(2);auto r2=Runtime::create(c);require(r1&&r2,"multiple runtimes");AgentId a{WorldId(1),1};require((*r1.value_if())->create_agent(a,AgentInit{},PsychTime(1)),"r1 create");require(!(*r2.value_if())->has_agent(a),"runtime isolation");std::cout<<"security ok\n";}
